* {
  box-sizing: border-box;
}
body {
  margin: 0;
  font-family: system-ui, sans-serif;
  color: #31594c;
  background: #e5eee0;
}
main {
  height: 100dvh;
  overflow: hidden;
  background: radial-gradient(ellipse at 45% 25%, #fff8e4, #d0e8df);
}
.canvas {
  position: absolute;
  inset: 0;
}
header {
  position: absolute;
  left: 25px;
  right: 25px;
  top: 22px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  font-size: 13px;
}
a {
  color: inherit;
  text-decoration: none;
  font-size: 23px;
  font-weight: 700;
}
button {
  cursor: pointer;
  border: 1px solid #ffffff80;
  background: #faffeecc;
  color: #31594c;
