}
header span {
  margin-right: auto;
}
.score {
  position: absolute;
  top: 82px;
  right: 25px;
  background: #ffffeccc;
  border-radius: 14px;
  padding: 15px;
}
footer {
  position: absolute;
  bottom: 24px;
  left: 0;
  right: 0;
  text-align: center;
  font-size: 11px;
  color: #6e8d7b;
  pointer-events: none;
}
.win,
.message {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
