  border-radius: 20px;
  padding: 30px;
  text-align: center;
  min-width: 300px;
}
.win h1 {
  font-size: 29px;
  font-weight: 500;
  letter-spacing: -1px;
}
.win p {
  font-size: 12px;
}
.controls {
  display: none;
}
.webgl-fallback {
  position: absolute;
  top: 40%;
  left: 10%;
  right: 10%;
  text-align: center;
}
@media (max-width: 700px) {
  header {
    left: 15px;
