  .controls button {
    width: 45px;
    height: 45px;
    padding: 0;
    touch-action: none;
    font-size: 20px;
  }
  .controls button:last-child {
    margin-left: auto;
  }
  footer {
    bottom: 90px;
    font-size: 9px;
  }
}

