import * as THREE from "three";
import { mergeGeometries } from "three/addons/utils/BufferGeometryUtils.js";
import type { Entity } from "./protocol";
export function entityGeometry(entity: Entity): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [];
  const coarse = entity.geometry?.detail === "coarse";
  const segments = coarse ? 6 : 14;
  const add = (
    g: THREE.BufferGeometry,
    p = [0, 0, 0],
    s = [1, 1, 1],
    color = entity.color,
    r = [0, 0, 0],
  ) => {
    let geometry = g.index ? g.toNonIndexed() : g;
    if (geometry !== g) g.dispose();
    geometry.deleteAttribute("uv");
    geometry.applyMatrix4(
      new THREE.Matrix4().compose(
        new THREE.Vector3(...p),
        new THREE.Quaternion().setFromEuler(
          new THREE.Euler(...(r as [number, number, number])),
        ),
        new THREE.Vector3(...s),
      ),
    );
    const c = new THREE.Color(color);
    const colors = new Float32Array(geometry.attributes.position.count * 3);
    for (let i = 0; i < colors.length; i += 3) {
      colors[i] = c.r;
      colors[i + 1] = c.g;
      colors[i + 2] = c.b;
    }
    geometry.setAttribute("color", new THREE.BufferAttribute(colors, 3));
    parts.push(geometry);
  };
  const sphere = (p: number[], s: number[], c = entity.color) =>
    add(new THREE.SphereGeometry(1, segments, segments), p, s, c);
  const cylinder = (p: number[], s: number[], c = entity.color) =>
    add(new THREE.CylinderGeometry(0.65, 1, 1, segments), p, s, c);
  switch (entity.geometry?.kind) {
    case "tree":
      cylinder([0, 0.8, 0], [0.2, 1.6, 0.2], "#98775a");
      sphere([0, 2, 0], [0.95, 1.05, 0.9]);
      if (!coarse) {
        sphere([-0.55, 1.65, 0.15], [0.6, 0.75, 0.6]);
        sphere([0.55, 1.9, 0.15], [0.55, 0.7, 0.55]);
      }
      break;
    case "mushroom":
      cylinder([0, 0.7, 0], [0.25, 1.4, 0.25], "#f6ebd3");
      sphere([0, 1.5, 0], [1.15, 0.65, 1.15]);
      if (!coarse)
        for (let i = 0; i < 7; i++)
          sphere(
            [
              Math.cos(i * 2.4) * 0.7,
              1.94 + Math.sin(i) * 0.05,
              Math.sin(i * 2.4) * 0.7,
            ],
            [0.13, 0.045, 0.13],
            "#fff1de",
          );
      break;
    case "platform":
      add(new THREE.BoxGeometry(1, 0.45, 1, 2, 2, 2), [0, 0.2, 0]);
      add(
        new THREE.BoxGeometry(0.9, 0.1, 0.9),
        [0, 0.47, 0],
        [1, 1, 1],
        "#fff2cf",
      );
      break;
    case "arch":
      for (const x of [-0.8, 0.8]) {
        cylinder([x, 1, 0], [0.24, 2, 0.25]);
        add(new THREE.BoxGeometry(0.65, 0.2, 0.65), [x, 0.1, 0]);
      }
      add(new THREE.TorusGeometry(0.8, 0.23, 8, 24, Math.PI), [0, 1.85, 0]);
      if (!coarse) sphere([0, 2.75, 0], [0.16, 0.16, 0.16], "#f8d88d");
      break;
    case "crystal":
      add(
        new THREE.OctahedronGeometry(0.65, 0),
        [0, 0.5, 0],
        [0.65, 1.25, 0.65],
      );
      break;
    case "pond":
      cylinder([0, 0.02, 0], [1.3, 0.055, 1], "#d3d7a8");
      cylinder([0, 0.06, 0], [1.2, 0.065, 0.9], entity.color);
      break;
    case "flower":
      cylinder([0, 0.5, 0], [0.055, 1, 0.055], "#779963");
      for (let i = 0; i < (coarse ? 4 : 7); i++) {
        const a = (i * Math.PI * 2) / (coarse ? 4 : 7);
        sphere(
          [Math.cos(a) * 0.3, 1.04, Math.sin(a) * 0.3],
          [0.26, 0.15, 0.26],
        );
      }
      sphere([0, 1.12, 0], [0.19, 0.13, 0.19], "#ffdf92");
      sphere([0.19, 0.4, 0], [0.3, 0.08, 0.12], "#91b878");
      break;
    case "rock":
      sphere([0, 0.35, 0], [0.7, 0.55, 0.6]);
      sphere([0.55, 0.18, 0.15], [0.35, 0.3, 0.4]);
      break;
    case "custom":
      for (const part of entity.geometry.parts ?? []) {
        const g =
          part.shape === "box"
            ? new THREE.BoxGeometry(1, 1, 1, 2, 2, 2)
            : part.shape === "cone"
              ? new THREE.ConeGeometry(1, 1, segments)
              : part.shape === "cylinder"
                ? new THREE.CylinderGeometry(1, 1, 1, segments)
                : part.shape === "torus"
                  ? new THREE.TorusGeometry(0.7, 0.25, 8, segments)
                  : new THREE.SphereGeometry(1, segments, segments);
        add(g, part.position, part.scale, part.color, part.rotation);
      }
      break;
    default:
      sphere([0, 0.65, 0], [0.5, 0.5, 0.5], "#bceee0");
  }
  if (!parts.length) sphere([0, 0.5, 0], [0.5, 0.5, 0.5]);
  const merged = mergeGeometries(parts);
  parts.forEach((g) => g.dispose());
  merged.computeBoundingSphere();
  return merged;
}
export function addFormationSource(
  geometry: THREE.BufferGeometry,
  previous?: Float32Array,
) {
  const position = geometry.getAttribute("position");
  const source = new Float32Array(position.count * 3);
  for (let i = 0; i < position.count; i++) {
    if (previous) {
      const n = (i % (previous.length / 3)) * 3;
      source[i * 3] = previous[n];
      source[i * 3 + 1] = previous[n + 1];
      source[i * 3 + 2] = previous[n + 2];
    } else {
      const y = 1 - (2 * (i + 0.5)) / position.count,
        a = i * 2.399963,
        r = Math.sqrt(1 - y * y) * 0.58;
      source[i * 3] = Math.cos(a) * r;
      source[i * 3 + 1] = y * 0.58 + 0.7;
      source[i * 3 + 2] = Math.sin(a) * r;
    }
  }
  geometry.setAttribute("aFrom", new THREE.BufferAttribute(source, 3));
  return geometry;
}
export function terrainValue(x: number, y: number, z: number) {
  return (
    Math.sin(x * 2.3 + Math.cos(z * 3.1)) * Math.cos(y * 2.8 - z) +
    Math.sin(z * 4 + x * 1.3) * 0.32 +
    Math.sin(y * 7 - z * 4) * 0.15
  );
}

src/lib/gameplay.ts:
import type { Entity } from "./protocol";

export type Vec3 = [number, number, number];

export type PlayerState = {
  position: Vec3;
  velocityY: number;
  groundedOn?: string;
  supportPosition?: Vec3;
  supportTop?: number;
};

export type PlayerInput = {
  x: number;
  z: number;
  jump: boolean;
};

export type GameplayStep = PlayerState & {
  collected: string[];
  won: boolean;
};

const GROUND_CENTER_Y = 0.42;
const PLAYER_HALF_HEIGHT = 0.42;
const MOVE_SPEED = 4;
const JUMP_SPEED = 6;
const GRAVITY = 15;

export function movingEntityPosition(entity: Entity, time: number): Vec3 {
  const position: Vec3 = [...entity.position];
  if (entity.stage === "ready" && entity.behavior?.type === "move") {
    const axis = entity.behavior.axis ?? "y";
    const index = axis === "x" ? 0 : axis === "y" ? 1 : 2;
    position[index] +=
      Math.sin(time * (entity.behavior.speed ?? 1)) *
      (entity.behavior.amplitude ?? 0.5);
  }
  return position;
}

export function isTextEntryTarget(target: EventTarget | null) {
  return (
    target instanceof Element &&
    Boolean(target.closest("input,textarea,select,[contenteditable]"))
  );
}

function platformTop(entity: Entity, time: number) {
  const position = movingEntityPosition(entity, time);
  return {
    id: entity.id,
    x: position[0],
    z: position[2],
    y: position[1] + 0.52 * entity.scale[1] + PLAYER_HALF_HEIGHT,
    halfX: entity.scale[0] * 0.55,
    halfZ: entity.scale[2] * 0.55,
    bounce: entity.behavior?.type === "bounce",
  };
}

export function stepGameplay(
  state: PlayerState,
  input: PlayerInput,
  entities: Entity[],
  collectedBefore: readonly string[],
  time: number,
  delta: number,
): GameplayStep {
  const dt = Math.min(Math.max(delta, 0), 0.04);
  const position: Vec3 = [...state.position];
  const readyPlatforms = entities.filter(
    (entity) =>
      entity.stage === "ready" && entity.geometry?.kind === "platform",
  );

  // A grounded player inherits the exact displacement of a moving platform.
  // This also makes compatible speed/amplitude edits reconcile without a reset.
  if (state.groundedOn) {
    const support = readyPlatforms.find(
      (entity) => entity.id === state.groundedOn,
    );
    if (support) {
      const before =
        state.supportPosition ?? movingEntityPosition(support, time - dt);
      const after = movingEntityPosition(support, time);
      position[0] += after[0] - before[0];
      const afterTop = platformTop(support, time).y;
      const beforeTop =
        state.supportTop ??
        before[1] + 0.52 * support.scale[1] + PLAYER_HALF_HEIGHT;
      position[1] += afterTop - beforeTop;
      position[2] += after[2] - before[2];
    }
  }

  const magnitude = Math.hypot(input.x, input.z);
  if (magnitude) {
    position[0] += (input.x / magnitude) * MOVE_SPEED * dt;
    position[2] += (input.z / magnitude) * MOVE_SPEED * dt;
  }

  let velocityY = state.velocityY;
  let groundedOn = state.groundedOn;
  let supportPosition = state.supportPosition;
  let supportTop = state.supportTop;
  const wasSupported =
    Boolean(groundedOn) || position[1] <= GROUND_CENTER_Y + 0.04;
  if (input.jump && wasSupported) {
    velocityY = JUMP_SPEED;
    groundedOn = undefined;
    supportPosition = undefined;
    supportTop = undefined;
  }
  velocityY -= GRAVITY * dt;
  const previousY = position[1];
  position[1] += velocityY * dt;

  let floor = GROUND_CENTER_Y;
  let floorId: string | undefined;
  let bounce = false;
  for (const entity of readyPlatforms) {
    const platform = platformTop(entity, time);
    const inside =
      Math.abs(position[0] - platform.x) <= platform.halfX &&
      Math.abs(position[2] - platform.z) <= platform.halfZ;
    // Only land while descending and crossing a top surface. This avoids
    // teleporting onto a platform when walking below or beside it.
    if (
      inside &&
      velocityY <= 0 &&
      previousY >= platform.y - 0.08 &&
      position[1] <= platform.y &&
      platform.y >= floor
    ) {
      floor = platform.y;
      floorId = platform.id;
      bounce = platform.bounce;
    }
  }
  if (position[1] <= floor) {
    position[1] = floor;
    velocityY = bounce ? JUMP_SPEED * 1.18 : 0;
    groundedOn = bounce ? undefined : floorId;
    supportPosition = floorId
      ? movingEntityPosition(
          readyPlatforms.find((entity) => entity.id === floorId)!,
          time,
        )
      : undefined;
    supportTop = floorId ? floor : undefined;
  } else if (!floorId) {
    groundedOn = undefined;
    supportPosition = undefined;
    supportTop = undefined;
  }

  const radius = Math.hypot(position[0], position[2]);
  if (radius > 8.4) {
    position[0] *= 8.4 / radius;
    position[2] *= 8.4 / radius;
  }

  const collected = [...collectedBefore];
  for (const entity of entities) {
    if (entity.stage !== "ready") continue;
    const entityPosition = movingEntityPosition(entity, time);
    const distance = Math.hypot(
      position[0] - entityPosition[0],
      position[2] - entityPosition[2],
    );
    if (
      entity.behavior?.type === "collect" &&
      distance < 0.85 &&
      !collected.includes(entity.id)
    )
      collected.push(entity.id);
  }
  const collectibleIds = entities
    .filter(
      (entity) =>
        entity.stage === "ready" && entity.behavior?.type === "collect",
    )
    .map((entity) => entity.id);
  const won = entities.some((entity) => {
    if (entity.stage !== "ready" || entity.behavior?.type !== "portal")
      return false;
    const portal = movingEntityPosition(entity, time);
    return (
      collectibleIds.every((id) => collected.includes(id)) &&
      Math.hypot(position[0] - portal[0], position[2] - portal[2]) < 1.2
    );
  });
  return {
    position,
    velocityY,
    groundedOn,
    supportPosition,
    supportTop,
    collected,
    won,
  };
}

